export class HarnessMemoryStore{constructor({maxActive=8,minConfidence=0.5}={}){this.maxActive=maxActive;this.minConfidence=minConfidence;this.items=[];}record(item){if(!item.tenantId||!item.projectId||!item.userId||!item.harness||!item.id)throw new TypeError('Complete harness memory namespace is required');this.items.push(Object.freeze({...item}));return item;}select(scope){const current=Date.now();return this.items.filter(x=>x.tenantId===scope.tenantId&&x.projectId===scope.projectId&&x.userId===scope.userId&&x.harness===scope.harness&&x.confidence>=this.minConfidence&&Date.parse(x.validUntil)>current).sort((a,b)=>b.confidence-a.confidence||a.id.localeCompare(b.id)).slice(0,this.maxActive);}}
